


/** Immutable posted financial movement with signed amount, per-card sequence, merchant sequence and balance snapshots. Corrections create new transactions. */ export type GiftCardTransaction = { "amount_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; "balance_after_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; "balance_before_money": { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "amount": string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": "USD" | (string & {}); }; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "gift_card_id": string; "gift_card_transaction_id": string; "idempotency_key": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "merchant_sequence": string; "order_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "posted_at": string; "reason": "" | "complimentary" | "balance_accidentally_decreased" | "support_issue" | "suspicious_activity" | "balance_accidentally_increased" | "customer_request" | (string & {}); /** Use an exact numeric string, not a floating-point number. Format: int64. */ "sequence": string; "source_id": string; "source_type": "gift_card_load" | "gift_card_redemption" | "refund" | "gift_card_adjustment" | "external_cash_out" | "gift_card_purchase_refund" | "gift_card_manual_purchase_reversal" | "gift_card_funding_disposition" | "gift_card_purchase_refund_recovery" | (string & {}); "transaction_type": "load" | "import" | "redeem" | "refund" | "refund_transfer" | "adjustment" | "cash_out" | "purchase_reversal" | "funding_loss_accepted" | "purchase_refund_recovery" | "purchase_refund_recovery_transfer" | (string & {}); };
